// Some portions generated by Claude
/** Undo and redo as two stacks of snapshots: the past (newest last) and the future (next first). */
export type HistoryStacks<T> = { readonly past: readonly T[]; readonly future: readonly T[] };

/** A change was made: its "before" snapshot goes on the past (the newest `limit` are kept); the future is gone. */
export function recorded<T>(stacks: HistoryStacks<T>, snapshot: T, limit: number): HistoryStacks<T> {
  return { past: [...stacks.past.slice(-(limit - 1)), snapshot], future: [] };
}

/** The snapshot to go back to, with `current` kept for redo; null when there is nothing to undo. */
export function undone<T>(stacks: HistoryStacks<T>, current: T, limit: number) {
  const snapshot = stacks.past.at(-1);
  if (snapshot === undefined) return null;
  return { snapshot, stacks: { past: stacks.past.slice(0, -1), future: [current, ...stacks.future.slice(0, limit - 1)] } };
}

/** The snapshot to go forward to, with `current` kept for undo; null when there is nothing to redo. */
export function redone<T>(stacks: HistoryStacks<T>, current: T, limit: number) {
  const snapshot = stacks.future[0];
  if (snapshot === undefined) return null;
  return { snapshot, stacks: { past: [...stacks.past.slice(-(limit - 1)), current], future: stacks.future.slice(1) } };
}
